//! `jsrt::array` against `fixtures/arrays.json`, generated by Node 26.

mod common;

use common::*;
use jsrt::array::slice;

#[test]
fn slice_matches_node() {
    let fixture = fixture("arrays.json");
    let cases = arr(&fixture["slice"]);
    assert!(cases.len() > 3000);
    for case in cases {
        let case = arr(case);
        let n = i32_of(&case[0]);
        let (start, end) = (i32_of(&case[1]), opt_i32(&case[2]));
        let expected: Vec<i32> = arr(&case[3]).iter().map(i32_of).collect();
        let v: Vec<i32> = (0..n).collect();
        assert_eq!(slice(&v, start, end), &expected[..], "[0..{n}].slice({start}, {end:?})");
    }
}
